-- Accounts that can sign in. Conventions for all migrations:
--   * UUID primary keys, generated by the application
--   * snake_case, singular table names; TIMESTAMPTZ for instants (UTC)
--   * explicit, named constraints and indexes (pk_*, fk_*, uk_*, ix_*, ck_*)
--   * never edit a migration that has been applied anywhere; add a new one instead
--
-- platform_role is platform-wide. What a user may do for a specific mosque is NOT stored here but in
-- mosque_administrator (V4), so rights are always scoped to one mosque.

CREATE TABLE app_user (
    id            UUID         NOT NULL,
    email         VARCHAR(254) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    display_name  VARCHAR(100) NOT NULL,
    platform_role VARCHAR(20)  NOT NULL,
    status        VARCHAR(20)  NOT NULL,
    created_at    TIMESTAMPTZ  NOT NULL,
    updated_at    TIMESTAMPTZ  NOT NULL,
    version       BIGINT       NOT NULL,
    CONSTRAINT pk_app_user PRIMARY KEY (id),
    CONSTRAINT uk_app_user_email UNIQUE (email),
    -- the application stores normalized (lower-case) emails; enforce it so uniqueness is case-insensitive
    CONSTRAINT ck_app_user_email_lowercase CHECK (email = lower(email)),
    CONSTRAINT ck_app_user_platform_role CHECK (platform_role IN ('PLATFORM_ADMIN', 'USER')),
    CONSTRAINT ck_app_user_status CHECK (status IN ('ACTIVE', 'BLOCKED'))
);
